          "contentHtml": "<div class=\"p-3.5 rounded-xl bg-[#fffdf7] border-2 border-[#151b20] font-mono text-xs overflow-x-auto shadow-[4px_4px_0px_#151b20] my-2\">\n  <div class=\"text-[10px] text-[#0e7490] font-black mb-1.5 uppercase tracking-wider pb-1 border-b-2 border-[#151b20]/15 flex items-center justify-between\">\n    <span>Production Implementation / Type-Safe Listing:</span>\n    <span class=\"text-[#151b20] text-[9px] bg-[#eee4c8] px-2 py-0.5 rounded border border-[#151b20]\">Python 3.10+</span>\n  </div>\n  <pre class=\"leading-relaxed bg-[#fffaf0] p-2.5 rounded-lg border border-[#151b20] text-[#151b20] overflow-x-auto\"><code># mia_memorization_sim.py\n# Simulates loss-based Membership Inference Attack (MIA) on a classification model\n\nfrom typing import Dict, Tuple, List\nimport numpy as np\n\ndef compute_mia_scores(\n    in_sample_losses: np.ndarray,\n    out_of_sample_losses: np.ndarray,\n    threshold: float\n) -&gt; Dict[str, float]:\n    # Evaluates attacker precision, recall, and accuracy in identifying training records\n    tp = np.sum(in_sample_losses &lt;= threshold)\n    fn = np.sum(in_sample_losses &gt; threshold)\n    fp = np.sum(out_of_sample_losses &lt;= threshold)\n    tn = np.sum(out_of_sample_losses &gt; threshold)\n    \n    precision = float(tp / (tp + fp)) if (tp + fp) &gt; 0 else 0.0\n    recall = float(tp / (tp + fn)) if (tp + fn) &gt; 0 else 0.0\n    accuracy = float((tp + tn) / (len(in_sample_losses) + len(out_of_sample_losses)))\n    \n    return {\n        &quot;precision&quot;: preci</code></pre>\n</div>"
